record.field:
if records:
    total = len(records)
    # Separar lotes estables de los pendientes
    stable = records.filtered(lambda b: b.sync_stable)
    pending = records - stable

    enqueued = 0
    errors = []
    for idx, batch in enumerate(pending, 1):
        try:
            _logger.info(f"Encolando lote {idx}/{len(pending)}: {batch.name}")
            batch.with_context(prefetch_fields=False).action_download()
            # action_download solo encola el lote (state='queued'). El cron
            # 'Auto-sync lotes SAT' lo procesara cada 2 minutos.
            env.cr.commit()
            enqueued += 1
        except Exception as e:
            _logger.error(f"Error encolando lote {batch.name}: {str(e)}")
            errors.append(batch.name or f"Lote-{batch.id}")

    msg_parts = []
    if enqueued:
        msg_parts.append(
            f"⏳ {enqueued} lote(s) encolados. El cron los procesara en los proximos minutos."
        )
    if stable:
        msg_parts.append(
            f"⏭️ {len(stable)} lote(s) omitidos por estar marcados como "
            f"'Sincronizacion completa'."
        )
    if errors:
        msg_parts.append(f"❌ {len(errors)} lote(s) con error: {', '.join(str(x) for x in errors)}")
    if not pending:
        msg_parts.append(
            "ℹ️ Todos los lotes seleccionados ya estan sincronizados. Si deseas "
            "forzar la actualizacion usa el boton individual 'Actualizar Lote'."
        )

    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Lotes SAT encolados',
            'message': ' | '.join(msg_parts),
            'type': 'info' if not errors else 'warning',
            'sticky': True,
        }
    }
